.board-stats {
    display: flex;
    gap: 1.5rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 8px;
    margin-bottom: 1rem;
    flex-wrap: wrap;
}

.board-stats .stat {
    font-weight: 600;
    font-size: 0.9rem;
}

.board-stats .stat-overdue {
    color: #dc3545;
}

.board-search {
    margin-bottom: 1rem;
}

.board-search input {
    width: 100%;
    max-width: 400px;
    padding: 0.5rem 0.75rem;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    font-size: 0.95rem;
}

